// Expenses page: the list and the total.
function total(items) {
  return items.reduce((sum, item) => sum + item.amount, 0);
}
module.exports = { total };
// Monthly report page: total per category.
function totalsByCategory(items) {
  const out = {};
  for (const item of items) {
    out[item.category] = (out[item.category] || 0) + item.amount;
  }
  return out;
}
module.exports = { totalsByCategory };
// Budget page: how much is left of the monthly budget.
function remaining(items, budget) {
  let spent = 0;
  for (const item of items) spent = spent + item.amount;
  return budget - spent;
}
module.exports = { remaining };
